import{_ as e,c as p,e as t,a as n,d as r,w as i,r as l,o,b as d}from"./app-CHV3pEDi.js";const c="/assets/RTOS%E5%86%85%E6%A0%B8%E4%BA%94%E5%A4%A7%E7%BB%84%E6%88%90%E7%BB%93%E6%9E%84%E5%9B%BE-DrOGRwy4.jpg",E="/assets/%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%E6%8A%A2%E5%8D%A0%E7%A4%BA%E6%84%8F%E5%9B%BE-N6ihzLnn.jpg",T="/assets/%E5%90%8C%E4%BC%98%E5%85%88%E7%BA%A7%E6%97%B6%E9%97%B4%E7%89%87%E8%BD%AE%E8%BD%AC%E7%A4%BA%E6%84%8F%E5%9B%BE-SCWRYZK9.jpg",h="/assets/%E4%BB%BB%E5%8A%A1%E5%B0%B1%E7%BB%AA%E9%98%9F%E5%88%97%E4%B8%8E%E5%BB%B6%E6%97%B6%E9%98%9F%E5%88%97%E7%BB%93%E6%9E%84%E5%9B%BE-DM0HACnE.jpg",m="/assets/RT-Thread%E4%BB%BB%E5%8A%A1%E9%97%B4%E9%80%9A%E4%BF%A1%E6%9C%BA%E5%88%B6%E5%88%86%E7%B1%BB%E5%9B%BE-PsP-1pDF.jpg",B="/assets/RT-Thread%E5%88%86%E5%B1%82%E7%BB%84%E4%BB%B6%E6%9E%B6%E6%9E%84%E5%9B%BE-BY0O8S3N.jpg",R={};function g(S,s){const a=l("VPLink");return o(),p("div",null,[s[4]||(s[4]=t('<p>很多人在使用RTOS的时候，每天都在调用各种API来完成创建任务、获取信号量等操作。如果使用多个不同的RTOS，会发现这些RTOS虽然提供的API不同，但是基本功能却是类似的。</p><p>那么，<strong>一个RTOS内核里面到底有哪些东西？这些东西各自负责什么？</strong> 在这篇文章中将进行简要说明，从而帮助你对RTOS的组成和功能有整体理解。将来无论用到哪种具体的RTOS，都能做到心中有数。</p><p>此外，如果你想真正搞懂RTOS，甚至想自己写一个，也需要搞清楚这个问题。</p><h2 id="一、rtos内核的常见组成" tabindex="-1"><a class="header-anchor" href="#一、rtos内核的常见组成"><span>一、RTOS内核的常见组成</span></a></h2><p>简单来说，一个完整的RTOS内核通常至少由以下五个部分组成。</p><p><img src="'+c+'" alt="RTOS内核五大组成结构图"></p><p>接下来，让我们分别来看每个部分的作用。</p><h3 id="调度器" tabindex="-1"><a class="header-anchor" href="#调度器"><span>调度器</span></a></h3><p>可以说，调度器是RTOS内核的核心，即整个系统的&quot;心脏&quot;。</p><p>它的<strong>主要工作是负责决定当前应该让哪个任务占用CPU运行，以及什么时候切换到另一个任务</strong>。</p><p>调度器的核心是调度算法，不同RTOS可能采用不同的调度算法，常见的调度算法有：优先级调度、时间片轮转等等。不同的RTOS可能同时采用多种不同的调度算法。</p><p>例如，RT-Thread采用的是<strong>优先级抢占式调度加同优先级时间片轮转</strong>的混合调度策略。具体来说，当一个高优先级任务就绪时，它会立即抢占当前正在运行的低优先级任务。</p><p><img src="'+E+'" alt="高优先级抢占示意图"></p><p>而对于相同优先级的多个任务，则按照时间片轮流执行，每个任务用完自己的时间片后，调度器就会切换到下一个同优先级任务。</p><p><img src="'+T+'" alt="同优先级时间片轮转示意图"></p><p>每当有任务状态发生变化，或者系统时钟中断到来时，调度器就会运行一次，根据算法选出下一个要运行的任务，然后触发上下文切换。</p><h3 id="任务管理" tabindex="-1"><a class="header-anchor" href="#任务管理"><span>任务管理</span></a></h3><p><strong>任务管理负责管理所有任务的生命周期，包括任务的创建、删除、挂起、恢复等等。</strong></p><p>任务管理通过一个叫做**任务控制块（TCB）**的数据结构，来维护每个任务的状态、优先级、栈指针、寄存器现场等信息。在前面的文章中，我们已经看到过RTOS通常采用特定的结构体来描述任务控制块。</p><p>在RTOS内部，<strong>不同的任务往往会根据其运行状态，被组织成多条不同的队列</strong>，例如就绪队列和延时队列。</p><p><img src="'+h+'" alt="任务就绪队列与延时队列结构图"></p><p>可以说，任务管理是调度器的基础，因为调度器需要知道有哪些任务、每个任务处于什么状态，才能做出正确的调度决策。</p><h3 id="任务间通信与同步" tabindex="-1"><a class="header-anchor" href="#任务间通信与同步"><span>任务间通信与同步</span></a></h3><p>虽然任务之间是独立运行的，但是，<strong>任务之间往往需要交换数据、共享资源、协调执行顺序。为了解决这种需求，RTOS提供了任务通信与同步机制</strong>。</p><p>例如，在RT-Thread中，提供了信号量、互斥锁、事件、邮箱、消息队列等多种IPC机制，每种机制适用于不同的场景。</p><p><img src="'+m+`" alt="RT-Thread任务间通信机制分类图"></p><p><strong>常见任务通信与同步机制包括信号量、互斥锁、消息队列、事件标志等等。</strong></p><p>例如，当两个任务需要共享一个硬件资源时，就可以用互斥锁来保证同一时间只有一个任务访问。而如果一个任务需要等另一个任务完成某些工作后再继续运行，就可以用信号量来同步。如果两个任务之间需要传递数据，可以使用消息队列机制进行通信。</p><h3 id="时间管理" tabindex="-1"><a class="header-anchor" href="#时间管理"><span>时间管理</span></a></h3><p><strong>RTOS的时间管理以系统时钟Tick为基础，提供任务延时、软件定时器、时间片轮转等功能</strong>。</p><p>系统每隔固定的时间（比如1毫秒）产生一次时钟中断，时间管理机制就在这个中断里更新系统时间、检查延时是否到期、触发定时器回调等等。</p><p>可以说，时间管理是整个RTOS的&quot;脉搏&quot;。</p><h3 id="内存管理" tabindex="-1"><a class="header-anchor" href="#内存管理"><span>内存管理</span></a></h3><p>在实际应用中，不仅任务创建时需要分配栈空间，创建信号量、消息队列等内核对象时也需要分配内存，任务本身可能也要动态分配内存来完成具体的工作。</p><p>内存管理就是负责这些动态内存的分配和回收。常见的内存管理方式有两种：一种是通用的堆管理，类似于C语言的malloc和free。另一种是定长内存块管理，预先划分好固定大小的内存块，分配和回收都很快，而且不会产生碎片。</p><p>在RT-Thread中，通常同时提供了以上两种不同的管理方式。例如，堆管理使用rt_malloc和rt_free接口，内部根据内存大小自动选择小内存管理算法或slab算法；而内存池则使用rt_mp_create创建，通过rt_mp_alloc和rt_mp_free进行分配和回收。</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-"><span class="line"><span>/* 堆管理：分配任意大小 */</span></span>
<span class="line"><span>void *buf = rt_malloc(128);</span></span>
<span class="line"><span>if (buf != RT_NULL) {</span></span>
<span class="line"><span>    rt_free(buf);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/* 内存池：分配固定大小的块 */</span></span>
<span class="line"><span>static rt_uint8_t pool_buf[1024];</span></span>
<span class="line"><span>struct rt_mempool *mp = rt_mp_create(&quot;test_mp&quot;, pool_buf, 1024, 64);</span></span>
<span class="line"><span>void *block = rt_mp_alloc(mp, RT_WAITING_FOREVER);</span></span>
<span class="line"><span>if (block != RT_NULL) {</span></span>
<span class="line"><span>    rt_mp_free(block);</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="二、rtos的其它组件" tabindex="-1"><a class="header-anchor" href="#二、rtos的其它组件"><span>二、RTOS的其它组件</span></a></h2><p>除了内核本身外，很多RTOS还提供了丰富的可选组件，这些组件不属于内核的核心部分，但是，用户可以根据项目需要选择性地引入，从而快速构建完整的应用系统。</p><p>以RT-Thread为例，它提供了一个分层的组件架构：</p><p><img src="`+B+'" alt="RT-Thread分层组件架构图"></p><p>这些组件的作用和特点各不相同：</p><ol><li><strong>文件系统（DFS）</strong>：提供统一的文件操作接口，支持FatFS、DevFS等多种文件系统，让开发者可以像在PC上一样操作文件和目录。</li><li><strong>命令行（FinSH）</strong>：提供一个交互式的命令行终端，可以通过输入命令来查看系统状态、调用函数、调试问题。</li><li><strong>网络协议栈（LwIP）</strong>：提供TCP/IP协议栈，支持Socket、HTTP、MQTT等网络功能。</li><li><strong>设备驱动框架</strong>：提供PIN、I2C、SPI、UART、ADC、PWM等标准化的设备驱动接口。</li><li><strong>电源管理（PM）</strong>：提供低功耗管理功能，支持空闲休眠、深度睡眠、唤醒源配置等。</li></ol><p>为了面向不同的应用需求，这些组件都是可选的，用户可以根据项目的实际需求和资源限制，来决定引入哪些组件。</p><p>引入这些组件有助于快速获得成熟的功能，避免重复造轮子；不过，会增加代码体积、内存占用和系统的复杂度。</p><p>因此，在资源受限的场景中，只需要内核本身就够了；而在功能丰富、资源富裕的网产品中，则可以引入更多组件来加速开发。</p><h2 id="三、总结" tabindex="-1"><a class="header-anchor" href="#三、总结"><span>三、总结</span></a></h2><p>综上所述，RTOS内核通常由调度器、任务管理、任务间通信与同步、时间管理、内存管理这五个部分组成。</p><p>除了内核之外，很多RTOS还提供了文件系统、命令行、网络协议栈、设备驱动框架等可选组件，开发者可以根据项目需求选择性引入。</p><p>如果你想进一步理解这五个部分在底层到底是如何实现的，甚至想亲手把它们一个个写出来，那么从空白工程开始手写一个RTOS内核，会是最直接有效的方式。当你亲手实现了调度算法、任务切换、消息队列这些功能之后，RTOS对你来说就不再是一个黑盒了。</p><hr>',51)),n("blockquote",null,[s[1]||(s[1]=n("p",null,"如果你希望系统地学习RTOS底层原理，可以了解我的《RTOS开发与实战》课程。",-1)),s[2]||(s[2]=n("p",null,"课程不是简单地讲解FreeRTOS API的使用，而是带你从零开始编写一个RTOS内核，逐步实现任务管理、任务调度、上下文切换、同步与通信等核心机制，并通过一个远程温湿度监控设备项目，将操作系统原理应用到实际嵌入式开发中。",-1)),s[3]||(s[3]=n("p",null,"适合希望深入理解RTOS工作原理、提升嵌入式底层开发能力的同学。",-1)),n("p",null,[r(a,{href:"/blog/diyrtos/"},{default:i(()=>[...s[0]||(s[0]=[d("课程详情",-1)])]),_:1})])])])}const O=e(R,[["render",g]]),b=JSON.parse('{"path":"/tech/rtos100/vb56zdzw/","title":"一个RTOS内核通常由哪些部分组成","lang":"zh-CN","frontmatter":{"title":"一个RTOS内核通常由哪些部分组成","createTime":"2026/11/10 14:55:12","permalink":"/tech/rtos100/vb56zdzw/","description":"很多人在使用RTOS的时候，每天都在调用各种API来完成创建任务、获取信号量等操作。如果使用多个不同的RTOS，会发现这些RTOS虽然提供的API不同，但是基本功能却是类似的。 那么，一个RTOS内核里面到底有哪些东西？这些东西各自负责什么？ 在这篇文章中将进行简要说明，从而帮助你对RTOS的组成和功能有整体理解。将来无论用到哪种具体的RTOS，都能做...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"一个RTOS内核通常由哪些部分组成\\",\\"image\\":[\\"\\"],\\"dateModified\\":null,\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://lishutong1024.cn/tech/rtos100/vb56zdzw/"}],["meta",{"property":"og:site_name","content":"李述铜的嵌入式课堂"}],["meta",{"property":"og:title","content":"一个RTOS内核通常由哪些部分组成"}],["meta",{"property":"og:description","content":"很多人在使用RTOS的时候，每天都在调用各种API来完成创建任务、获取信号量等操作。如果使用多个不同的RTOS，会发现这些RTOS虽然提供的API不同，但是基本功能却是类似的。 那么，一个RTOS内核里面到底有哪些东西？这些东西各自负责什么？ 在这篇文章中将进行简要说明，从而帮助你对RTOS的组成和功能有整体理解。将来无论用到哪种具体的RTOS，都能做..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}]]},"readingTime":{"minutes":7.73,"words":2318},"git":{},"autoDesc":true,"filePathRelative":"notes/tech/rtos100/base/q09.md","headers":[],"bulletin":true}');export{O as comp,b as data};
